    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &Args,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    let ipv6_regex = Regex::new(
        r"(([0-9a-fA-F]{0,4}:){2,7}[0-9a-fA-F]{0,4}|::([0-9a-fA-F]{0,4}:){0,6}[0-9a-fA-F]{0,4}|([0-9a-fA-F]{0,4}:){1,7}:|([0-9a-fA-F]{0,4}:){1,6}:[0-9a-fA-F]{0,4})",
    )
    .unwrap();

    for cap in ipv6_regex.find_iter(line) {
        let ipv6 = cap.as_str();
        if should_include(ipv6, args) {
            let output = if args.clean {
                ipv6.to_string()
            } else {
                line.to_string()
            };

            results.push((
                "ipv6_address".to_string(),
                output,
                if args.line { Some(line_num) } else { None },
                file_name.clone(),
            ));
        }
    }
}

fn extract_macs(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &Args,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    let mac_regex = Regex::new(r"(?i)(?:[0-9a-f]{2}[:-]){5}(?:[0-9a-f]{2})").unwrap();

    for cap in mac_regex.find_iter(line) {
        let mac = cap.as_str();
        if should_include(mac, args) {
