fn extract_credit_cards(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &Args,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    let cc_regex = Regex::new(r"\b\d{4}[\s-]?\d{4}[\s-]?\d{4}[\s-]?\d{4}\b").unwrap();

    for cap in cc_regex.find_iter(line) {
        let cc = cap.as_str();
        if should_include(cc, args) {
            let output = if args.clean {
                cc.to_string()
            } else {
