fn extract_file_paths(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &Args,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Match Windows paths and Unix paths, and filenames
    let file_patterns = vec![
        r"(?i)[a-zA-Z]:[\\\/][\w\\\/\-\.]+",  // Windows paths
        r"\/[a-zA-Z0-9\/_\-\.]*",              // Unix paths
        r"\b[a-zA-Z0-9_\-]+\.[a-zA-Z0-9]{2,4}\b", // Filenames
    ];

    for pattern in file_patterns {
        if let Ok(regex) = Regex::new(pattern) {
            for cap in regex.find_iter(line) {
                let file_path = cap.as_str();
                if should_include(file_path, args) {
                    let output = if args.clean {
                        file_path.to_string()
                    } else {
                        line.to_string()
                    };

                    results.push((
                        "files".to_string(),
                        output,
                        if args.line { Some(line_num) } else { None },
                        file_name.clone(),
                    ));
                }
            }
        }
    }
}

