fn extract_from_text(
    content: &str,
    file_name: String,
    args: &Args,
    extract_all: bool,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    for (line_num, line) in content.lines().enumerate() {
        process_line(&line, line_num + 1, Some(file_name.clone()), args, extract_all, results);
    }
}

