use clap::Parser;
use regex::Regex;
use std::fs::{self, File};
use std::io::{self, BufRead, BufReader, Write};
use std::path::PathBuf;
use std::time::Instant;
use walkdir::WalkDir;

#[derive(Parser, Debug)]
#[command(name = "executable")]
#[command(about = "DataSurgeon - Extract sensitive data and patterns from text and files")]
struct Args {
    #[arg(short, long, default_value = "")]
    file: String,

    #[arg(long, default_value = "")]
    add: String,

    #[arg(long, default_value = "")]
    update: String,

    #[arg(long, default_value = "")]
    remove: String,

    #[arg(long)]
    list: bool,

