fn extract_urls(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &Args,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    let url_regex = Regex::new(
        r"(?i)(https?|ftp)://[^\s/$.?#].[^\s]*",
    )
    .unwrap();

    for cap in url_regex.find_iter(line) {
        let url = cap.as_str();
        if should_include(url, args) {
            let output = if args.clean {
                url.to_string()
            } else {
                line.to_string()
            };

            results.push((
                "url".to_string(),
                output,
                if args.line { Some(line_num) } else { None },
                file_name.clone(),
