fn parse_arguments(args: &[String], parsed: &mut ParsedArgs) {
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-f" | "--file" => {
                if i + 1 < args.len() {
                    parsed.file = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-C" | "--clean" => {
                parsed.clean = true;
                i += 1;
            }
            "--directory" => {
                if i + 1 < args.len() {
                    parsed.directory = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "--ignore" => {
                parsed.ignore = true;
                i += 1;
            }
