// Extract URLs
fn extract_urls(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Match http://, https://, ftp://
    let protocols = ["http://", "https://", "ftp://"];

    for protocol in &protocols {
        let mut search_pos = 0;
        while let Some(pos) = line[search_pos..].find(protocol) {
            let start = search_pos + pos;
            let mut end = start + protocol.len();

            // Find end of URL
            while end < line.len() && !line.chars().nth(end).unwrap().is_whitespace() {
                end += 1;
            }

            let url_str = &line[start..end];
            if should_include(url_str, args) {
                let output = if args.clean {
                    url_str.to_string()
                } else {
                    line.to_string()
                };
                results.push((
                    "url".to_string(),
                    output,
                    if args.line { Some(line_num) } else { None },
                    file_name.clone(),
                ));
                if !args.thorough {
                    return;
                }
            }

            search_pos = end;
        }
    }
}

// Extract file paths
fn extract_file_paths(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Match Windows paths, Unix paths, and filenames
    let mut i = 0;
    let chars: Vec<char> = line.chars().collect();

    while i < chars.len() {
        // Windows path: X:\...
        if i + 1 < chars.len() && chars[i].is_alphabetic() && chars[i + 1] == ':' {
            let start = i;
            i += 2;
            if i < chars.len() && (chars[i] == '\\' || chars[i] == '/') {
                i += 1;
                while i < chars.len()
                    && (chars[i].is_alphanumeric() || "/\\.-_".contains(chars[i]))
                {
                    i += 1;
                }
                let path_str = &line[start..i];
                if should_include(path_str, args) {
                    let output = if args.clean {
                        path_str.to_string()
                    } else {
                        line.to_string()
                    };
                    results.push((
                        "files".to_string(),
                        output,
                        if args.line { Some(line_num) } else { None },
                        file_name.clone(),
                    ));
                    if !args.thorough {
                        return;
                    }
                }
            }
        }
        // Unix path: /...
        else if chars[i] == '/' {
            let start = i;
            i += 1;
            while i < chars.len() && (chars[i].is_alphanumeric() || "/-_.".contains(chars[i])) {
                i += 1;
            }
            if i > start + 1 {
                let path_str = &line[start..i];
                if should_include(path_str, args) {
                    let output = if args.clean {
                        path_str.to_string()
                    } else {
                        line.to_string()
                    };
                    results.push((
                        "files".to_string(),
                        output,
                        if args.line { Some(line_num) } else { None },
                        file_name.clone(),
                    ));
                    if !args.thorough {
                        return;
                    }
                }
            }
        }
        // Filename: xxx.yyy
        else if chars[i].is_alphanumeric() || chars[i] == '_' || chars[i] == '-' {
            let start = i;
            while i < chars.len()
                && (chars[i].is_alphanumeric() || "_-.".contains(chars[i]))
            {
                i += 1;
            }
            if i < chars.len() && chars[i] == '.' {
                i += 1;
                let ext_start = i;
                while i < chars.len() && chars[i].is_alphanumeric() {
                    i += 1;
                }
                if i > ext_start {
                    let file_str = &line[start..i];
                    if should_include(file_str, args) {
