        let c = chars[i];
        if !in_email && (c.is_alphanumeric() || "._%-".contains(c)) {
            start = i;
            in_email = true;
        } else if in_email && c == '@' {
            // Continue in email
        } else if in_email && (c.is_alphanumeric() || ".-".contains(c)) {
            // Continue in email
        } else if in_email && c == '.' && i + 1 < chars.len() && (chars[i + 1].is_alphabetic()) {
            // Might be domain
        } else if in_email {
            if text[start..i].contains('@') && text[start..i].contains('.') {
