                        output,
                        if args.line { Some(line_num) } else { None },
                        file_name.clone(),
                    ));
                    if !args.thorough {
                        return;
                    }
                }
            }
        }
        // Filename: xxx.yyy
        else if chars[i].is_alphanumeric() || chars[i] == '_' || chars[i] == '-' {
            let start = i;
            while i < chars.len()
                && (chars[i].is_alphanumeric() || "_-.".contains(chars[i]))
            {
                i += 1;
            }
            if i < chars.len() && chars[i] == '.' {
                i += 1;
                let ext_start = i;
                while i < chars.len() && chars[i].is_alphanumeric() {
                    i += 1;
