use std::env;
use std::fs;
use std::io::{self, BufRead, BufReader, Write};
use std::time::Instant;

fn main() {
    let args: Vec<String> = env::args().collect();

    // Parse command line arguments
    let mut parsed_args = ParsedArgs::default();
    parse_arguments(&args, &mut parsed_args);

    // Get home directory
    let home_dir = env::var("HOME").unwrap_or_else(|_| "/home/agent".to_string());

    // Print plugin error message (to match original behavior)
    eprintln!(
        "Failed to open plugins.json file. PLUGIN_PATH: {}/.DataSurgeon/plugins.json",
        home_dir
    );

    if parsed_args.version {
        eprintln!("DataSurgeon: https://github.com/Drew-Alleman/DataSurgeon 1.2.8");
        return;
    }

    let start_time = Instant::now();

    // Determine extraction types
    let extract_all = !parsed_args.email
        && !parsed_args.phone
        && !parsed_args.hash
        && !parsed_args.ip_addr
        && !parsed_args.ipv6_addr
        && !parsed_args.mac_addr
        && !parsed_args.credit_card
        && !parsed_args.url
        && !parsed_args.files
        && !parsed_args.bitcoin
        && !parsed_args.aws
        && !parsed_args.google
        && !parsed_args.dns
        && !parsed_args.social;

    let mut results: Vec<(String, String, Option<usize>, Option<String>)> = Vec::new();

    // Handle directory option
    if !parsed_args.directory.is_empty() {
        walk_directory(&parsed_args.directory, &parsed_args, extract_all, &mut results);
    } else if !parsed_args.file.is_empty() {
        // Handle file option
        if let Ok(content) = fs::read_to_string(&parsed_args.file) {
            extract_from_text(
                &content,
                parsed_args.file.clone(),
                &parsed_args,
                extract_all,
                &mut results,
            );
        }
    } else {
        // Read from stdin
        if !parsed_args.suppress {
            eprintln!("[*] Reading standard input. If you meant to analyze a file use 'ds -f <FILE>' (ctrl+c to exit)");
        }

        let stdin = io::stdin();
        let reader = BufReader::new(stdin.lock());
        let mut line_num = 0;

        for line in reader.lines() {
            line_num += 1;
            if let Ok(line_content) = line {
                process_line(
                    &line_content,
                    line_num,
                    None,
                    &parsed_args,
                    extract_all,
                    &mut results,
                );
            }
        }
    }

    // Output results
    if !parsed_args.output.is_empty() {
        if let Ok(mut file) = fs::File::create(&parsed_args.output) {
            for (identifier, content, line_num, file_name) in results {
                let output_str = format_output(
                    &identifier,
                    &content,
                    line_num,
                    &file_name,
                    &parsed_args,
                );
                writeln!(file, "{}", output_str).ok();
            }
        }
    } else {
        for (identifier, content, line_num, file_name) in results {
            let output_str = format_output(&identifier, &content, line_num, &file_name, &parsed_args);
            println!("{}", output_str);
        }
    }

    if parsed_args.time {
        let elapsed = start_time.elapsed();
        let hours = elapsed.as_secs() / 3600;
        let minutes = (elapsed.as_secs() % 3600) / 60;
        let seconds = elapsed.as_secs() % 60;
        eprintln!("[*] Time elapsed: {:02}h:{:02}m:{:02}s", hours, minutes, seconds);
    }
}

#[derive(Default)]
struct ParsedArgs {
    file: String,
    add: String,
    update: String,
    remove: String,
    list: bool,
    clean: bool,
    directory: String,
    ignore: bool,
    line: bool,
    thorough: bool,
    display: bool,
    suppress: bool,
    drop: String,
    filter: String,
    hide: bool,
    output: String,
    time: bool,
    email: bool,
    phone: bool,
    hash: bool,
    ip_addr: bool,
    ipv6_addr: bool,
    mac_addr: bool,
    credit_card: bool,
    url: bool,
    files: bool,
    bitcoin: bool,
    aws: bool,
    google: bool,
    dns: bool,
    social: bool,
    version: bool,
}

fn parse_arguments(args: &[String], parsed: &mut ParsedArgs) {
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-f" | "--file" => {
                if i + 1 < args.len() {
                    parsed.file = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-C" | "--clean" => {
                parsed.clean = true;
                i += 1;
            }
            "--directory" => {
                if i + 1 < args.len() {
                    parsed.directory = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "--ignore" => {
                parsed.ignore = true;
                i += 1;
            }
            "-l" | "--line" => {
                parsed.line = true;
                i += 1;
            }
            "-T" | "--thorough" => {
                parsed.thorough = true;
                i += 1;
            }
            "-D" | "--display" => {
                parsed.display = true;
                i += 1;
            }
            "-S" | "--suppress" => {
                parsed.suppress = true;
                i += 1;
            }
            "--drop" => {
                if i + 1 < args.len() {
                    parsed.drop = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "--filter" => {
                if i + 1 < args.len() {
                    parsed.filter = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-X" | "--hide" => {
                parsed.hide = true;
                i += 1;
            }
            "-o" | "--output" => {
                if i + 1 < args.len() {
                    parsed.output = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-t" | "--time" => {
                parsed.time = true;
                i += 1;
            }
            "-e" | "--email" => {
                parsed.email = true;
                i += 1;
            }
            "-p" | "--phone" => {
                parsed.phone = true;
                i += 1;
            }
            "-H" | "--hash" => {
                parsed.hash = true;
                i += 1;
            }
            "-i" | "--ip-addr" => {
                parsed.ip_addr = true;
                i += 1;
            }
            "-6" | "--ipv6-addr" => {
                parsed.ipv6_addr = true;
                i += 1;
            }
            "-m" | "--mac-addr" => {
                parsed.mac_addr = true;
                i += 1;
            }
            "-c" | "--credit-card" => {
                parsed.credit_card = true;
                i += 1;
            }
            "-u" | "--url" => {
                parsed.url = true;
                i += 1;
            }
            "-F" | "--files" => {
                parsed.files = true;
                i += 1;
            }
            "-b" | "--bitcoin" => {
                parsed.bitcoin = true;
                i += 1;
            }
            "-a" | "--aws" => {
                parsed.aws = true;
                i += 1;
            }
            "-g" | "--google" => {
                parsed.google = true;
                i += 1;
            }
            "-d" | "--dns" => {
                parsed.dns = true;
                i += 1;
            }
            "-s" | "--social" => {
                parsed.social = true;
                i += 1;
            }
            "-V" | "--version" => {
                parsed.version = true;
                i += 1;
            }
            _ => {
                i += 1;
            }
        }
    }
}

fn walk_directory(
    dir: &str,
    args: &ParsedArgs,
    extract_all: bool,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_file() {
                if let Ok(content) = fs::read_to_string(&path) {
                    let path_str = path.to_string_lossy().to_string();
                    extract_from_text(&content, path_str, args, extract_all, results);
                }
            } else if path.is_dir() {
                walk_directory(&path.to_string_lossy(), args, extract_all, results);
            }
        }
    }
}

fn extract_from_text(
    content: &str,
    file_name: String,
    args: &ParsedArgs,
    extract_all: bool,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    for (line_num, line) in content.lines().enumerate() {
        process_line(
            line,
            line_num + 1,
            Some(file_name.clone()),
            args,
            extract_all,
            results,
        );
    }
}

fn process_line(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    extract_all: bool,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Apply filter if specified
    if !args.filter.is_empty() {
        if !simple_regex_match(&args.filter, line) {
            return;
        }
    }

    let extract_email = args.email || extract_all;
    let extract_phone = args.phone;
    let extract_hash = args.hash;
    let extract_ip = args.ip_addr;
    let extract_ipv6 = args.ipv6_addr;
    let extract_mac = args.mac_addr;
    let extract_cc = args.credit_card;
    let extract_url = args.url;
    let extract_files = args.files;
    let extract_bitcoin = args.bitcoin;
    let extract_aws = args.aws;
    let extract_google = args.google;
    let extract_dns = args.dns;
    let extract_ssn = args.social;

    // Extract emails
    if extract_email {
        extract_emails(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract phone numbers
    if extract_phone {
        extract_phones(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract hashes
    if extract_hash {
        extract_hashes(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract IP addresses
    if extract_ip {
        extract_ips(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract IPv6 addresses
    if extract_ipv6 {
        extract_ipv6s(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract MAC addresses
    if extract_mac {
        extract_macs(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract credit cards
    if extract_cc {
        extract_credit_cards(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract URLs
    if extract_url {
        extract_urls(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract files
    if extract_files {
        extract_file_paths(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract bitcoin wallets
    if extract_bitcoin {
        extract_bitcoins(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract AWS keys
    if extract_aws {
        extract_aws_keys(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract Google keys
    if extract_google {
        extract_google_keys(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract DNS records
    if extract_dns {
        extract_dns_records(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract social security numbers
    if extract_ssn {
        extract_ssns(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }
}

fn should_include(content: &str, args: &ParsedArgs) -> bool {
    if !args.drop.is_empty() {
        if simple_regex_match(&args.drop, content) {
            return false;
        }
    }
    true
}

fn format_output(
    identifier: &str,
    content: &str,
    line_num: Option<usize>,
    file_name: &Option<String>,
    args: &ParsedArgs,
) -> String {
    if args.line && args.display {
        format!(
            "{}, file: {} {}, line: {}",
            identifier,
            file_name.as_ref().unwrap_or(&String::new()),
            content,
            line_num.unwrap_or(0)
        )
    } else if args.line {
        format!("{}, {}, line: {}", identifier, content, line_num.unwrap_or(0))
    } else if args.display {
        format!(
            "{}, file: {} {}",
            identifier,
            file_name.as_ref().unwrap_or(&String::new()),
            content
        )
    } else {
        let identifier_str = if args.hide {
            String::new()
        } else {
            format!("{}: ", identifier)
        };
        format!("{}{}", identifier_str, content)
    }
}

// Simple regex matcher
fn simple_regex_match(pattern: &str, text: &str) -> bool {
    if pattern.starts_with('^') {
        let pattern_rest = &pattern[1..];
        if pattern_rest.ends_with('$') {
            let pattern_middle = &pattern_rest[..pattern_rest.len() - 1];
            text == pattern_middle || text.starts_with(&pattern_middle.replace("\\[", "[").replace("\\]", "]"))
        } else {
            text.starts_with(&pattern_rest.replace("\\[", "[").replace("\\]", "]"))
        }
    } else if pattern.ends_with('$') {
        let pattern_rest = &pattern[..pattern.len() - 1];
        text.ends_with(pattern_rest)
    } else {
        text.contains(pattern)
    }
}

// Extract emails
fn extract_emails(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Simple email matching
    let mut i = 0;
    let chars: Vec<char> = line.chars().collect();

    while i < chars.len() {
        // Look for start of email
        if chars[i].is_alphanumeric() || "._%-".contains(chars[i]) {
            let start = i;
            while i < chars.len() && (chars[i].is_alphanumeric() || "._%-".contains(chars[i])) {
                i += 1;
            }
            // Look for @
            if i < chars.len() && chars[i] == '@' {
                i += 1;
                let domain_start = i;
                while i < chars.len() && (chars[i].is_alphanumeric() || ".-".contains(chars[i])) {
                    i += 1;
                }
                let email_str = &line[start..i];
                if email_str.contains('@') && email_str.contains('.') && !email_str.ends_with('.') {
                    if should_include(email_str, args) {
                        let output = if args.clean {
                            email_str.to_string()
                        } else {
                            line.to_string()
                        };
                        results.push((
                            "email".to_string(),
                            output,
                            if args.line { Some(line_num) } else { None },
                            file_name.clone(),
                        ));
                    }
                }
            }
        } else {
            i += 1;
        }
    }
}

