) {
    // AWS keys start with AKIA and are 20 characters total
    if let Some(pos) = line.to_uppercase().find("AKIA") {
        if pos + 20 <= line.len() {
            let key = &line[pos..pos + 20];
            if key[4..].chars().all(|c| c.is_ascii_alphanumeric()) {
                if should_include(key, args) {
