// Extract Google keys
fn extract_google_keys(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Google keys are 40-character hex strings
    let mut i = 0;
    while i + 40 <= line.len() {
        let chunk = &line[i..i + 40];
        if chunk.chars().all(|c| c.is_ascii_hexdigit()) {
            let start_ok = i == 0 || !line.chars().nth(i - 1).unwrap().is_alphanumeric();
            let end_ok =
                i + 40 >= line.len() || !line.chars().nth(i + 40).unwrap().is_alphanumeric();

            if start_ok && end_ok && should_include(chunk, args) {
                let output = if args.clean {
