fn parse_arguments(args: &[String], parsed: &mut ParsedArgs) {
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-f" | "--file" => {
                if i + 1 < args.len() {
                    parsed.file = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-C" | "--clean" => {
                parsed.clean = true;
                i += 1;
            }
            "--directory" => {
                if i + 1 < args.len() {
                    parsed.directory = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "--ignore" => {
                parsed.ignore = true;
                i += 1;
            }
            "-l" | "--line" => {
                parsed.line = true;
                i += 1;
            }
            "-T" | "--thorough" => {
                parsed.thorough = true;
                i += 1;
            }
            "-D" | "--display" => {
                parsed.display = true;
                i += 1;
            }
            "-S" | "--suppress" => {
                parsed.suppress = true;
                i += 1;
            }
            "--drop" => {
                if i + 1 < args.len() {
                    parsed.drop = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "--filter" => {
                if i + 1 < args.len() {
                    parsed.filter = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-X" | "--hide" => {
                parsed.hide = true;
                i += 1;
            }
            "-o" | "--output" => {
                if i + 1 < args.len() {
                    parsed.output = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-t" | "--time" => {
                parsed.time = true;
                i += 1;
            }
            "-e" | "--email" => {
                parsed.email = true;
                i += 1;
            }
            "-p" | "--phone" => {
                parsed.phone = true;
                i += 1;
            }
            "-H" | "--hash" => {
                parsed.hash = true;
                i += 1;
            }
            "-i" | "--ip-addr" => {
                parsed.ip_addr = true;
                i += 1;
            }
            "-6" | "--ipv6-addr" => {
                parsed.ipv6_addr = true;
                i += 1;
            }
            "-m" | "--mac-addr" => {
                parsed.mac_addr = true;
                i += 1;
            }
            "-c" | "--credit-card" => {
                parsed.credit_card = true;
                i += 1;
            }
            "-u" | "--url" => {
                parsed.url = true;
                i += 1;
            }
            "-F" | "--files" => {
                parsed.files = true;
                i += 1;
            }
            "-b" | "--bitcoin" => {
                parsed.bitcoin = true;
                i += 1;
            }
            "-a" | "--aws" => {
                parsed.aws = true;
                i += 1;
            }
            "-g" | "--google" => {
                parsed.google = true;
                i += 1;
            }
            "-d" | "--dns" => {
                parsed.dns = true;
                i += 1;
