fn walk_directory(
    dir: &str,
    args: &ParsedArgs,
    extract_all: bool,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_file() {
                if let Ok(content) = fs::read_to_string(&path) {
                    let path_str = path.to_string_lossy().to_string();
                    extract_from_text(&content, path_str, args, extract_all, results);
                }
            } else if path.is_dir() {
                walk_directory(&path.to_string_lossy(), args, extract_all, results);
            }
        }
    }
}

fn extract_from_text(
    content: &str,
    file_name: String,
    args: &ParsedArgs,
    extract_all: bool,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    for (line_num, line) in content.lines().enumerate() {
        process_line(
            line,
            line_num + 1,
            Some(file_name.clone()),
            args,
            extract_all,
            results,
        );
    }
}

fn process_line(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    extract_all: bool,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Apply filter if specified
    if !args.filter.is_empty() {
        if !simple_regex_match(&args.filter, line) {
            return;
        }
    }

    let extract_email = args.email || extract_all;
    let extract_phone = args.phone;
    let extract_hash = args.hash;
    let extract_ip = args.ip_addr;
    let extract_ipv6 = args.ipv6_addr;
    let extract_mac = args.mac_addr;
    let extract_cc = args.credit_card;
    let extract_url = args.url;
    let extract_files = args.files;
    let extract_bitcoin = args.bitcoin;
    let extract_aws = args.aws;
    let extract_google = args.google;
    let extract_dns = args.dns;
    let extract_ssn = args.social;

    // Extract emails
    if extract_email {
        extract_emails(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract phone numbers
    if extract_phone {
        extract_phones(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract hashes
    if extract_hash {
        extract_hashes(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract IP addresses
    if extract_ip {
        extract_ips(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract IPv6 addresses
    if extract_ipv6 {
        extract_ipv6s(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract MAC addresses
    if extract_mac {
        extract_macs(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract credit cards
    if extract_cc {
        extract_credit_cards(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract URLs
    if extract_url {
        extract_urls(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract files
    if extract_files {
        extract_file_paths(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract bitcoin wallets
    if extract_bitcoin {
        extract_bitcoins(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract AWS keys
    if extract_aws {
        extract_aws_keys(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract Google keys
    if extract_google {
        extract_google_keys(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract DNS records
    if extract_dns {
        extract_dns_records(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }

    // Extract social security numbers
    if extract_ssn {
        extract_ssns(line, line_num, file_name.clone(), args, results);
        if !args.thorough {
            return;
        }
    }
}

fn should_include(content: &str, args: &ParsedArgs) -> bool {
    if !args.drop.is_empty() {
        if simple_regex_match(&args.drop, content) {
            return false;
        }
    }
    true
}

fn format_output(
    identifier: &str,
    content: &str,
    line_num: Option<usize>,
    file_name: &Option<String>,
    args: &ParsedArgs,
) -> String {
    if args.line && args.display {
        format!(
            "{}, file: {} {}, line: {}",
            identifier,
            file_name.as_ref().unwrap_or(&String::new()),
            content,
            line_num.unwrap_or(0)
        )
    } else if args.line {
        format!("{}, {}, line: {}", identifier, content, line_num.unwrap_or(0))
    } else if args.display {
        format!(
            "{}, file: {} {}",
            identifier,
            file_name.as_ref().unwrap_or(&String::new()),
            content
        )
    } else {
        let identifier_str = if args.hide {
            String::new()
        } else {
            format!("{}: ", identifier)
        };
        format!("{}{}", identifier_str, content)
    }
}

// Simple regex matcher
fn simple_regex_match(pattern: &str, text: &str) -> bool {
    if pattern.starts_with('^') {
        let pattern_rest = &pattern[1..];
        if pattern_rest.ends_with('$') {
            let pattern_middle = &pattern_rest[..pattern_rest.len() - 1];
            text == pattern_middle || text.starts_with(&pattern_middle.replace("\\[", "[").replace("\\]", "]"))
        } else {
            text.starts_with(&pattern_rest.replace("\\[", "[").replace("\\]", "]"))
        }
    } else if pattern.ends_with('$') {
        let pattern_rest = &pattern[..pattern.len() - 1];
        text.ends_with(pattern_rest)
    } else {
        text.contains(pattern)
    }
}

// Extract emails
fn extract_emails(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Simple email matching
    let mut i = 0;
    let chars: Vec<char> = line.chars().collect();

    while i < chars.len() {
        // Look for start of email
        if chars[i].is_alphanumeric() || "._%-".contains(chars[i]) {
            let start = i;
            while i < chars.len() && (chars[i].is_alphanumeric() || "._%-".contains(chars[i])) {
                i += 1;
            }
            // Look for @
            if i < chars.len() && chars[i] == '@' {
                i += 1;
                let domain_start = i;
                while i < chars.len() && (chars[i].is_alphanumeric() || ".-".contains(chars[i])) {
                    i += 1;
                }
                let email_str = &line[start..i];
                if email_str.contains('@') && email_str.contains('.') && !email_str.ends_with('.') {
                    if should_include(email_str, args) {
                        let output = if args.clean {
                            email_str.to_string()
                        } else {
                            line.to_string()
                        };
                        results.push((
                            "email".to_string(),
                            output,
                            if args.line { Some(line_num) } else { None },
                            file_name.clone(),
                        ));
                    }
                }
            }
        } else {
            i += 1;
        }
    }
}

