            }

            if num_segments == 3 {
                let ip_str = &line[start..i];
                // Validate IP format
                let parts: Vec<&str> = ip_str.split('.').collect();
                if parts.len() == 4 {
                    let mut valid = true;
                    for part in &parts {
                        if let Ok(num) = part.parse::<u32>() {
                            if num > 255 {
                                valid = false;
                            }
                        } else {
                            valid = false;
                        }
                    }
                    if valid && should_include(ip_str, args) {
                        let output = if args.clean {
                            ip_str.to_string()
                        } else {
                            line.to_string()
                        };
                        results.push((
                            "ip_address".to_string(),
                            output,
                            if args.line { Some(line_num) } else { None },
                            file_name.clone(),
                        ));
                        if !args.thorough {
                            return;
                        }
                    }
                }
            }
        } else {
            i += 1;
        }
    }
}

// Extract IPv6 addresses
fn extract_ipv6s(
