    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Match pattern: XX:XX:XX:XX:XX:XX or XX-XX-XX-XX-XX-XX
    let mut i = 0;
    let chars: Vec<char> = line.chars().collect();

    while i < chars.len() {
        if chars[i].is_ascii_hexdigit() {
            let start = i;
            let mut segments = 0;
            let mut valid = true;

            while i < chars.len() && segments < 6 {
                // Expect 2 hex digits
                if i + 1 >= chars.len()
                    || !chars[i].is_ascii_hexdigit()
                    || !chars[i + 1].is_ascii_hexdigit()
                {
                    valid = false;
                    break;
                }
                i += 2;
                segments += 1;

                if segments < 6 {
                    if i < chars.len() && (chars[i] == ':' || chars[i] == '-') {
                        i += 1;
                    } else {
                        valid = false;
                        break;
                    }
                }
            }

            if valid && segments == 6 {
                let mac_str = &line[start..i];
                if should_include(mac_str, args) {
                    let output = if args.clean {
                        mac_str.to_string()
                    } else {
                        line.to_string()
                    };
                    results.push((
                        "mac_address".to_string(),
                        output,
                        if args.line { Some(line_num) } else { None },
                        file_name.clone(),
                    ));
                    if !args.thorough {
                        return;
                    }
                }
            }
        }
        i += 1;
    }
}

// Extract credit cards
fn extract_credit_cards(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Match pattern: XXXX XXXX XXXX XXXX or XXXX-XXXX-XXXX-XXXX
    let mut i = 0;
    let chars: Vec<char> = line.chars().collect();

    while i < chars.len() {
        if chars[i].is_numeric() {
            let start = i;
            let mut segments = 0;
            let mut valid = true;

            while i < chars.len() && segments < 4 {
                // Expect 4 digits
                for _ in 0..4 {
                    if i >= chars.len() || !chars[i].is_numeric() {
                        valid = false;
                        break;
                    }
                    i += 1;
                }

                segments += 1;

                if valid && segments < 4 {
                    if i < chars.len() && (chars[i] == '-' || chars[i] == ' ') {
                        i += 1;
                    } else {
                        valid = false;
                        break;
                    }
                }
            }

            if valid && segments == 4 {
                let cc_str = &line[start..i];
                if should_include(cc_str, args) {
