fn should_include(content: &str, args: &ParsedArgs) -> bool {
    if !args.drop.is_empty() {
        // The drop filter EXCLUDES matches
        // So if the content matches the drop pattern, exclude it
        if matches_pattern(&args.drop, content) {
            return false;
        }
    }
    true
}

fn format_output(
    identifier: &str,
    content: &str,
    line_num: Option<usize>,
    file_name: &Option<String>,
    args: &ParsedArgs,
) -> String {
    if args.line && args.display {
        format!(
            "{}, file: {} {}, line: {}",
            identifier,
            file_name.as_ref().unwrap_or(&String::new()),
            content,
            line_num.unwrap_or(0)
        )
    } else if args.line {
        format!("{}, {}, line: {}", identifier, content, line_num.unwrap_or(0))
    } else if args.display {
        format!(
            "{}, file: {} {}",
            identifier,
            file_name.as_ref().unwrap_or(&String::new()),
            content
        )
    } else {
        let identifier_str = if args.hide {
            String::new()
        } else {
            format!("{}: ", identifier)
        };
        format!("{}{}", identifier_str, content)
    }
}

// Simple regex matcher
fn simple_regex_match(pattern: &str, text: &str) -> bool {
    matches_pattern(pattern, text)
}

// Pattern matcher for simple regex patterns
fn matches_pattern(pattern: &str, text: &str) -> bool {
    // Handle ^ anchor
    if pattern.starts_with('^') {
        let pattern_rest = &pattern[1..];
        if pattern_rest.ends_with('$') {
            // ^pattern$
            let pattern_middle = &pattern_rest[..pattern_rest.len() - 1];
            return matches_exact_length(pattern_middle, text);
        } else {
            // ^pattern
            let pattern_clean = pattern_rest.replace("\\[", "[").replace("\\]", "]");
            return text.starts_with(&pattern_clean);
        }
    }

    // Handle $ anchor
    if pattern.ends_with('$') {
        let pattern_rest = &pattern[..pattern.len() - 1];
        let pattern_clean = pattern_rest.replace("\\[", "[").replace("\\]", "]");
        return text.ends_with(&pattern_clean);
    }

    // Default: substring match
    text.contains(pattern)
}

// Match exact length pattern like ^.{1,10}$
fn matches_exact_length(pattern: &str, text: &str) -> bool {
    if pattern == ".{1,10}" {
        let len = text.len();
        return len >= 1 && len <= 10;
    }

    if pattern == ".{1,}" {
        return !text.is_empty();
    }

    if pattern == ".{10}" {
        return text.len() == 10;
    }

    // For other patterns, just check exact match
    text == pattern
}

// Extract emails
fn extract_emails(
