// Extract MAC addresses
fn extract_macs(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Match pattern: XX:XX:XX:XX:XX:XX or XX-XX-XX-XX-XX-XX
    let mut i = 0;
    let chars: Vec<char> = line.chars().collect();

    while i < chars.len() {
        if chars[i].is_ascii_hexdigit() {
            let start = i;
            let mut segments = 0;
            let mut valid = true;

            while i < chars.len() && segments < 6 {
                // Expect 2 hex digits
                if i + 1 >= chars.len()
                    || !chars[i].is_ascii_hexdigit()
                    || !chars[i + 1].is_ascii_hexdigit()
                {
                    valid = false;
                    break;
                }
                i += 2;
                segments += 1;

                if segments < 6 {
                    if i < chars.len() && (chars[i] == ':' || chars[i] == '-') {
                        i += 1;
                    } else {
                        valid = false;
                        break;
                    }
                }
            }

            if valid && segments == 6 {
                let mac_str = &line[start..i];
                if should_include(mac_str, args) {
                    let output = if args.clean {
                        mac_str.to_string()
                    } else {
                        line.to_string()
                    };
                    results.push((
                        "mac_address".to_string(),
                        output,
                        if args.line { Some(line_num) } else { None },
                        file_name.clone(),
                    ));
                    if !args.thorough {
                        return;
                    }
                }
            }
        }
        i += 1;
    }
}

// Extract credit cards
fn extract_credit_cards(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Match pattern: XXXX XXXX XXXX XXXX or XXXX-XXXX-XXXX-XXXX
    let mut i = 0;
    let chars: Vec<char> = line.chars().collect();

    while i < chars.len() {
        if chars[i].is_numeric() {
            let start = i;
            let mut segments = 0;
            let mut valid = true;

            while i < chars.len() && segments < 4 {
                // Expect 4 digits
                for _ in 0..4 {
                    if i >= chars.len() || !chars[i].is_numeric() {
                        valid = false;
                        break;
                    }
                    i += 1;
                }

                segments += 1;

                if valid && segments < 4 {
                    if i < chars.len() && (chars[i] == '-' || chars[i] == ' ') {
                        i += 1;
                    } else {
                        valid = false;
                        break;
                    }
                }
            }

            if valid && segments == 4 {
                let cc_str = &line[start..i];
                if should_include(cc_str, args) {
                    let output = if args.clean {
                        cc_str.to_string()
                    } else {
                        line.to_string()
                    };
                    results.push((
                        "credit_card".to_string(),
                        output,
                        if args.line { Some(line_num) } else { None },
                        file_name.clone(),
                    ));
                    if !args.thorough {
                        return;
                    }
                }
            } else {
                i = start + 1;
            }
        } else {
            i += 1;
        }
    }
}

// Extract URLs
fn extract_urls(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Match http://, https://, ftp://
    let protocols = ["http://", "https://", "ftp://"];

    for protocol in &protocols {
        let mut search_pos = 0;
        while let Some(pos) = line[search_pos..].find(protocol) {
            let start = search_pos + pos;
            let mut end = start + protocol.len();

            // Find end of URL
            while end < line.len() && !line.chars().nth(end).unwrap().is_whitespace() {
                end += 1;
            }

            let url_str = &line[start..end];
            if should_include(url_str, args) {
                let output = if args.clean {
                    url_str.to_string()
                } else {
                    line.to_string()
                };
                results.push((
                    "url".to_string(),
                    output,
                    if args.line { Some(line_num) } else { None },
                    file_name.clone(),
                ));
                if !args.thorough {
                    return;
                }
            }

            search_pos = end;
        }
    }
}

// Extract file paths
fn extract_file_paths(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Match Windows paths, Unix paths, and filenames
    let mut i = 0;
    let chars: Vec<char> = line.chars().collect();

    while i < chars.len() {
        // Windows path: X:\...
        if i + 1 < chars.len() && chars[i].is_alphabetic() && chars[i + 1] == ':' {
            let start = i;
            i += 2;
            if i < chars.len() && (chars[i] == '\\' || chars[i] == '/') {
                i += 1;
                while i < chars.len()
                    && (chars[i].is_alphanumeric() || "/\\.-_".contains(chars[i]))
                {
                    i += 1;
                }
                let path_str = &line[start..i];
                if should_include(path_str, args) {
                    let output = if args.clean {
                        path_str.to_string()
                    } else {
                        line.to_string()
                    };
                    results.push((
                        "files".to_string(),
                        output,
                        if args.line { Some(line_num) } else { None },
                        file_name.clone(),
                    ));
                    if !args.thorough {
                        return;
                    }
                }
            }
        }
        // Unix path: /...
        else if chars[i] == '/' {
            let start = i;
            i += 1;
            while i < chars.len() && (chars[i].is_alphanumeric() || "/-_.".contains(chars[i])) {
                i += 1;
            }
            if i > start + 1 {
                let path_str = &line[start..i];
                if should_include(path_str, args) {
                    let output = if args.clean {
                        path_str.to_string()
                    } else {
                        line.to_string()
                    };
                    results.push((
                        "files".to_string(),
                        output,
                        if args.line { Some(line_num) } else { None },
                        file_name.clone(),
                    ));
                    if !args.thorough {
                        return;
                    }
                }
            }
        }
        // Filename: xxx.yyy
        else if chars[i].is_alphanumeric() || chars[i] == '_' || chars[i] == '-' {
            let start = i;
            while i < chars.len()
                && (chars[i].is_alphanumeric() || "_-.".contains(chars[i]))
            {
                i += 1;
            }
            if i < chars.len() && chars[i] == '.' {
                i += 1;
                let ext_start = i;
                while i < chars.len() && chars[i].is_alphanumeric() {
                    i += 1;
                }
                if i > ext_start {
                    let file_str = &line[start..i];
                    if should_include(file_str, args) {
                        let output = if args.clean {
                            file_str.to_string()
                        } else {
                            line.to_string()
                        };
                        results.push((
                            "files".to_string(),
                            output,
                            if args.line { Some(line_num) } else { None },
                            file_name.clone(),
                        ));
                        if !args.thorough {
                            return;
                        }
                    }
                }
            }
        } else {
            i += 1;
        }
    }
}

