// Extract IP addresses
fn extract_ips(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    let mut i = 0;
    let chars: Vec<char> = line.chars().collect();

    while i < chars.len() {
        if chars[i].is_numeric() {
            let start = i;
            let mut num_segments = 0;
            let mut last_dot = false;

            while i < chars.len() && (chars[i].is_numeric() || chars[i] == '.') {
                if chars[i] == '.' {
                    if last_dot {
                        break; // Double dot
                    }
                    last_dot = true;
                    num_segments += 1;
                } else {
                    last_dot = false;
                }
                i += 1;
            }

            if num_segments == 3 {
                let ip_str = &line[start..i];
                // Validate IP format
                let parts: Vec<&str> = ip_str.split('.').collect();
                if parts.len() == 4 {
                    let mut valid = true;
                    for part in &parts {
                        if let Ok(num) = part.parse::<u32>() {
                            if num > 255 {
                                valid = false;
                            }
                        } else {
                            valid = false;
                        }
                    }
                    if valid && should_include(ip_str, args) {
                        let output = if args.clean {
                            ip_str.to_string()
                        } else {
                            line.to_string()
                        };
                        results.push((
                            "ip_address".to_string(),
                            output,
                            if args.line { Some(line_num) } else { None },
                            file_name.clone(),
                        ));
                        if !args.thorough {
                            return;
                        }
                    }
                }
            }
        } else {
            i += 1;
        }
    }
}

// Extract IPv6 addresses
fn extract_ipv6s(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Simple IPv6 matching - look for multiple hex groups with colons
    let mut i = 0;
    while i < line.len() {
        if let Some(c) = line.chars().nth(i) {
            if c.is_ascii_hexdigit() || c == ':' {
                let start = i;
                let mut colon_count = 0;
                while i < line.len() {
                    if let Some(ch) = line.chars().nth(i) {
                        if ch.is_ascii_hexdigit() || ch == ':' {
                            if ch == ':' {
                                colon_count += 1;
                            }
                            i += 1;
                        } else {
                            break;
                        }
                    } else {
                        break;
                    }
                }

                if colon_count >= 2 {
                    let ipv6_str = &line[start..i];
                    if should_include(ipv6_str, args) {
                        let output = if args.clean {
                            ipv6_str.to_string()
                        } else {
                            line.to_string()
                        };
                        results.push((
                            "ipv6_address".to_string(),
                            output,
                            if args.line { Some(line_num) } else { None },
                            file_name.clone(),
                        ));
                        if !args.thorough {
                            return;
                        }
                    }
                }
            } else {
                i += 1;
            }
        } else {
            i += 1;
        }
    }
}

// Extract MAC addresses
fn extract_macs(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Match pattern: XX:XX:XX:XX:XX:XX or XX-XX-XX-XX-XX-XX
    let mut i = 0;
    let chars: Vec<char> = line.chars().collect();

    while i < chars.len() {
        if chars[i].is_ascii_hexdigit() {
            let start = i;
            let mut segments = 0;
            let mut valid = true;

            while i < chars.len() && segments < 6 {
                // Expect 2 hex digits
                if i + 1 >= chars.len()
                    || !chars[i].is_ascii_hexdigit()
                    || !chars[i + 1].is_ascii_hexdigit()
                {
                    valid = false;
                    break;
                }
                i += 2;
                segments += 1;

                if segments < 6 {
                    if i < chars.len() && (chars[i] == ':' || chars[i] == '-') {
                        i += 1;
                    } else {
                        valid = false;
                        break;
                    }
                }
            }

            if valid && segments == 6 {
                let mac_str = &line[start..i];
                if should_include(mac_str, args) {
                    let output = if args.clean {
                        mac_str.to_string()
                    } else {
                        line.to_string()
                    };
                    results.push((
                        "mac_address".to_string(),
                        output,
                        if args.line { Some(line_num) } else { None },
                        file_name.clone(),
                    ));
                    if !args.thorough {
                        return;
                    }
                }
            }
        }
        i += 1;
    }
}

// Extract credit cards
fn extract_credit_cards(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Match pattern: XXXX XXXX XXXX XXXX or XXXX-XXXX-XXXX-XXXX
    let mut i = 0;
    let chars: Vec<char> = line.chars().collect();

    while i < chars.len() {
        if chars[i].is_numeric() {
            let start = i;
            let mut segments = 0;
            let mut valid = true;

            while i < chars.len() && segments < 4 {
                // Expect 4 digits
                for _ in 0..4 {
                    if i >= chars.len() || !chars[i].is_numeric() {
                        valid = false;
                        break;
                    }
                    i += 1;
                }

                segments += 1;

                if valid && segments < 4 {
                    if i < chars.len() && (chars[i] == '-' || chars[i] == ' ') {
                        i += 1;
                    } else {
                        valid = false;
                        break;
                    }
                }
            }

            if valid && segments == 4 {
                let cc_str = &line[start..i];
                if should_include(cc_str, args) {
                    let output = if args.clean {
                        cc_str.to_string()
                    } else {
                        line.to_string()
                    };
                    results.push((
                        "credit_card".to_string(),
                        output,
                        if args.line { Some(line_num) } else { None },
                        file_name.clone(),
                    ));
                    if !args.thorough {
                        return;
                    }
                }
            } else {
                i = start + 1;
            }
        } else {
            i += 1;
        }
    }
}

// Extract URLs
fn extract_urls(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Match http://, https://, ftp://
    let protocols = ["http://", "https://", "ftp://"];

    for protocol in &protocols {
        let mut search_pos = 0;
        while let Some(pos) = line[search_pos..].find(protocol) {
            let start = search_pos + pos;
            let mut end = start + protocol.len();

            // Find end of URL
            while end < line.len() && !line.chars().nth(end).unwrap().is_whitespace() {
                end += 1;
            }

            let url_str = &line[start..end];
            if should_include(url_str, args) {
                let output = if args.clean {
                    url_str.to_string()
                } else {
                    line.to_string()
                };
                results.push((
                    "url".to_string(),
                    output,
                    if args.line { Some(line_num) } else { None },
                    file_name.clone(),
                ));
                if !args.thorough {
                    return;
                }
            }

            search_pos = end;
        }
    }
}

// Extract file paths
fn extract_file_paths(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Match Windows paths, Unix paths, and filenames
    let mut i = 0;
    let chars: Vec<char> = line.chars().collect();

    while i < chars.len() {
        // Windows path: X:\...
        if i + 1 < chars.len() && chars[i].is_alphabetic() && chars[i + 1] == ':' {
            let start = i;
            i += 2;
            if i < chars.len() && (chars[i] == '\\' || chars[i] == '/') {
                i += 1;
                while i < chars.len()
                    && (chars[i].is_alphanumeric() || "/\\.-_".contains(chars[i]))
                {
                    i += 1;
                }
                let path_str = &line[start..i];
                if should_include(path_str, args) {
                    let output = if args.clean {
                        path_str.to_string()
                    } else {
                        line.to_string()
                    };
                    results.push((
                        "files".to_string(),
                        output,
                        if args.line { Some(line_num) } else { None },
                        file_name.clone(),
                    ));
                    if !args.thorough {
                        return;
                    }
                }
            }
        }
        // Unix path: /...
        else if chars[i] == '/' {
            let start = i;
            i += 1;
            while i < chars.len() && (chars[i].is_alphanumeric() || "/-_.".contains(chars[i])) {
                i += 1;
            }
            if i > start + 1 {
                let path_str = &line[start..i];
                if should_include(path_str, args) {
                    let output = if args.clean {
                        path_str.to_string()
                    } else {
                        line.to_string()
                    };
                    results.push((
                        "files".to_string(),
                        output,
                        if args.line { Some(line_num) } else { None },
                        file_name.clone(),
                    ));
                    if !args.thorough {
                        return;
                    }
                }
            }
        }
        // Filename: xxx.yyy
        else if chars[i].is_alphanumeric() || chars[i] == '_' || chars[i] == '-' {
            let start = i;
            while i < chars.len()
                && (chars[i].is_alphanumeric() || "_-.".contains(chars[i]))
            {
                i += 1;
            }
            if i < chars.len() && chars[i] == '.' {
                i += 1;
                let ext_start = i;
                while i < chars.len() && chars[i].is_alphanumeric() {
                    i += 1;
                }
                if i > ext_start {
                    let file_str = &line[start..i];
                    if should_include(file_str, args) {
                        let output = if args.clean {
                            file_str.to_string()
                        } else {
                            line.to_string()
                        };
                        results.push((
                            "files".to_string(),
                            output,
                            if args.line { Some(line_num) } else { None },
                            file_name.clone(),
                        ));
                        if !args.thorough {
                            return;
                        }
                    }
                }
            }
        } else {
            i += 1;
        }
    }
}

// Extract bitcoin wallets
fn extract_bitcoins(
    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Bitcoin addresses start with 1, 3, or bc1 and are 26-35 characters
    let mut i = 0;
    let chars: Vec<char> = line.chars().collect();

    while i < chars.len() {
        if (chars[i] == '1' || chars[i] == '3') && i + 25 < chars.len() {
            let start = i;
            while i < line.len()
                && (chars[i].is_alphanumeric() && chars[i] != 'O' && chars[i] != 'I')
            {
                i += 1;
            }
            let len = i - start;
            if len >= 26 && len <= 35 {
                let addr = &line[start..i];
                if should_include(addr, args) {
                    let output = if args.clean {
                        addr.to_string()
                    } else {
                        line.to_string()
                    };
                    results.push((
                        "bitcoin_wallet".to_string(),
                        output,
                        if args.line { Some(line_num) } else { None },
                        file_name.clone(),
                    ));
                    if !args.thorough {
                        return;
                    }
                }
            }
        } else {
            i += 1;
        }
    }
}

// Extract AWS keys
fn extract_aws_keys(
