    while i < chars.len() {
        if chars[i].is_alphanumeric() {
            let start = i;
            let mut has_dot = false;

            while i < chars.len() && (chars[i].is_alphanumeric() || "-._".contains(chars[i])) {
                if chars[i] == '.' {
