    line: &str,
    line_num: usize,
    file_name: Option<String>,
    args: &ParsedArgs,
    results: &mut Vec<(String, String, Option<usize>, Option<String>)>,
) {
    // Match pattern: XXX-XX-XXXX
    let mut i = 0;
    let chars: Vec<char> = line.chars().collect();

    while i + 10 < chars.len() {
        if chars[i].is_numeric()
            && chars[i + 1].is_numeric()
            && chars[i + 2].is_numeric()
            && chars[i + 3] == '-'
            && chars[i + 4].is_numeric()
            && chars[i + 5].is_numeric()
            && chars[i + 6] == '-'
            && chars[i + 7].is_numeric()
            && chars[i + 8].is_numeric()
            && chars[i + 9].is_numeric()
            && chars[i + 10].is_numeric()
        {
            let ssn = &line[i..i + 11];
            if should_include(ssn, args) {
                let output = if args.clean {
                    ssn.to_string()
